// Helper functions for dynamic UI cascading dropdowns
function getItemCaseInsensitive(mapObj, keyVal) {
  if (!keyVal || !mapObj) return undefined
  if (mapObj[keyVal] !== undefined) return mapObj[keyVal]
  const upper = String(keyVal).toUpperCase()
  if (mapObj[upper] !== undefined) return mapObj[upper]
  const entry = Object.entries(mapObj).find(([k]) => k.toUpperCase() === upper)
  return entry ? entry[1] : undefined
}

export function corporationsForDistrict(district) {
  return getItemCaseInsensitive(CORPORATIONS_BY_DISTRICT, district) || []
}

export function municipalitiesForDistrict(district) {
  return getItemCaseInsensitive(MUNICIPALITIES_BY_DISTRICT, district) || []
}

export function townPanchayatsForDistrict(district) {
  return getItemCaseInsensitive(TOWN_PANCHAYATS_BY_DISTRICT, district) || []
}

export function wardsForCorporation(corpName) {
  for (const corpList of Object.values(CORPORATIONS_BY_DISTRICT)) {
    const found = corpList.find((c) => c.name === corpName)
    if (found) {
      return Array.from({ length: found.wards }, (_, i) => `Ward ${i + 1}`)
    }
  }
  return []
}

export function districtPanchayatWards(district) {
  const count = getItemCaseInsensitive(DISTRICT_PANCHAYAT_WARD_COUNT, district) || 0
  return Array.from({ length: count }, (_, i) => `Ward ${i + 1}`)
}

export function unionsForDistrict(district) {
  return getItemCaseInsensitive(PANCHAYAT_UNIONS_BY_DISTRICT, district) || []
}

export function blocksForDistrict(district) {
  return getItemCaseInsensitive(BLOCKS_BY_DISTRICT, district) || []
}

export function panchayatsForBlock(block) {
  return getItemCaseInsensitive(PANCHAYATS_BY_BLOCK, block) || []
}

export function positionsFor(bodyType) {
  if (bodyType === 'rural') return RURAL_POSITIONS
  if (bodyType === 'urban') return URBAN_POSITIONS
  return []
}
